'use strict';
const producerPanel=document.createElement('section');producerPanel.className='panel';producerPanel.innerHTML='<div class="section-title"><h2>e-ondiris</h2><span id="producer-status" class="badge"></span></div><p>Автоматическое пополнение «Бизнес → Производители». Страницы сохраняются сразу, повторный обход — через 6 часов после завершения. Рассылки не запускаются.</p><div class="actions"><button id="producer-start" class="outline">Включить сбор</button><button id="producer-pause" class="outline">Пауза</button><button id="producer-refresh" class="outline">Обновить</button></div><p id="producer-worker" class="rule-text"></p><p id="producer-error" role="status"></p><p id="producer-summary" class="rule-text"></p><div id="producer-metrics" class="stats source-metrics"></div>';collectionPage.querySelector('.heading').after(producerPanel);
let producerState=null,producerBusy=false;
async function refreshProducers(){if(producerBusy)return;producerBusy=true;try{const state=await api('/api/producers');producerState=state;const names={queued:'Сбор включён',fetching:'Сбор выполняется',waiting:'Ожидает следующего запроса',failed:'Повтор после ошибки',paused:'Приостановлен',idle:'Выключен'};document.getElementById('producer-status').textContent=state.enabled?(names[state.status]||'Сбор включён'):'Приостановлен';document.getElementById('producer-status').className='badge '+(state.enabled?'green':'');document.getElementById('producer-start').disabled=state.enabled;document.getElementById('producer-pause').disabled=!state.enabled;document.getElementById('producer-worker').textContent=(state.worker_alive?'Фоновый обработчик доступен.':'Фоновый обработчик не отвечает; запустите collect_producers.')+' Следующая страница: '+state.next_page+(state.next_attempt_at?' · Следующий запрос: '+new Date(state.next_attempt_at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}):'');document.getElementById('producer-error').textContent=state.error;const r=state.report;document.getElementById('producer-summary').textContent=r.organizations!==undefined?`За текущий обход: уникальных компаний ${r.organizations}. Создано клиентов: ${r.created_clients}. Дополнено: ${r.updated_clients}. Альтернативных значений: ${r.conflicts}.`:'Обход ещё не запускался.';const container=document.getElementById('producer-metrics');container.replaceChildren();for(const [title,value]of [['Компаний',r.organizations],['Email',r.unique_emails],['Телефонов',r.unique_phones],['Замечаний',r.issues]]){const article=document.createElement('article');const span=document.createElement('span');span.textContent=title;const strong=document.createElement('strong');strong.textContent=value??0;article.append(span,strong);container.append(article);}}catch(error){document.getElementById('producer-error').textContent=error.message;}finally{producerBusy=false;}}
async function producerAction(action){try{await api('/api/producers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});await refreshProducers();}catch(error){document.getElementById('producer-error').textContent=error.message;}}
document.getElementById('producer-start').onclick=()=>producerAction('start');document.getElementById('producer-pause').onclick=()=>producerAction('pause');document.getElementById('producer-refresh').onclick=refreshProducers;collectionButton.addEventListener('click',refreshProducers);setInterval(()=>{if(!collectionPage.hidden)refreshProducers();},5000);
